  'cappadocia-party': {tagline: 'A night among the fairy chimneys.', story: ['Cappadocia Party brings the magical atmosphere of Cappadocia to the venue with balloon motifs, warm light and Anatolian touches.', 'A night that reminds international guests of Türkiye’s most iconic landscape — an elegant close to a Turkish week.'], moments: ['Turkish week', 'Elegant night', 'Photo night']},
  'pink-pool-party': {tagline: 'Pink, sunshine and music.', story: ['Pink Pool Party turns the pool deck into a festival with pink décor, dancers and a DJ set.', 'It revives the pool area when the afternoon energy dips — a favourite daytime programme for younger and adult guests.'], moments: ['Poolside', 'Afternoon', 'Younger guests']},
